require('dotenv').config();
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Configuration priority:
// 1. Environment variables (for containerized deployments)
// 2. Secrets Manager (for production)
// 3. .env files (for local development only)

const secretsManager = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function loadFromSecretsManager(secretName) {
  // Only use Secrets Manager in production
  if (process.env.NODE_ENV !== 'production') {
    return null;
  }

  try {
    const response = await secretsManager.send(
      new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      })
    );

    if (response.SecretString) {
      return JSON.parse(response.SecretString);
    }
    return null;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      console.warn(`Secret ${secretName} not found in Secrets Manager`);
      return null;
    }
    console.error('Error loading secret from Secrets Manager:', error);
    return null;
  }
}

