    const dbSecrets = await secretsManager.getSecret('production/db-credentials');
    const apiSecrets = await secretsManager.getSecret('production/api-keys');

    process.env.DATABASE_URL = dbSecrets.connection_string;
    process.env.ANTHROPIC_API_KEY = apiSecrets.anthropic_key;
    process.env.STRIPE_SECRET_KEY = apiSecrets.stripe_key;

