// Required package.json dependencies:
// "dotenv": "^16.0.0"
// "dotenv-safe": "^8.2.0"

const dotenv = require('dotenv-safe');
const path = require('path');
const fs = require('fs');

// Secure .env configuration
const loadEnvironment = () => {
  // Only load .env in non-production environments
  if (process.env.NODE_ENV !== 'production') {
    const envPath = path.resolve(process.cwd(), `.env.${process.env.NODE_ENV || 'development'}`);

    // Validate .env file exists
    if (!fs.existsSync(envPath)) {
      console.error(`Environment file not found: ${envPath}`);
      process.exit(1);
    }

    // Load with schema validation
    dotenv.config({
      path: envPath,
      allowEmptyValues: false,
      example: path.resolve(process.cwd(), '.env.example')
    });

    // Validate required variables
    const requiredVars = [
      'DATABASE_URL',
      'JWT_SECRET',
      'NODE_env'
    ];

    const missing = requiredVars.filter(varName => !process.env[varName]);
    if (missing.length > 0) {
      console.error('Missing required environment variables:', missing);
      process.exit(1);
    }
  }

  // In production, all vars must be set via orchestration platform
  if (process.env.NODE_ENV === 'production') {
    const requiredProdVars = [
      'DATABASE_URL',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missing = requiredProdVars.filter(varName => !process.env[varName]);
    if (missing.length > 0) {
      console.error('Production missing required environment variables:', missing);
      process.exit(1);
    }
  }
};

