### 🔒 Security Best Practices for Secrets

#### 1. **Never Commit `.env` Files**
```bash
# Add to .gitignore
.env
.env.*.local
.env.production
.env.staging
*.key
*.pem
secrets/

# But commit .env.example with placeholder values
```

#### 2. **Create `.env.example`**
```bash
# .env.example - Template for required variables
DATABASE_URL=postgresql://user:password@host:5432/database
JWT_SECRET=generate-secure-random-string
AWS_ACCESS_KEY_ID=your-access-key
AWS_SECRET_ACCESS_KEY=your-secret-key
ANTHROPIC_API_KEY=your-api-key
STRIPE_SECRET_KEY=sk_test_...
LOGFIRE_TOKEN=your-token
NODE_ENV=development
PORT=3000
```

#### 3. **Encrypt Secrets at Rest (Vault)**

```javascript
// Using HashiCorp Vault
const nodeVault = require('node-vault')();

const vaultClient = nodeVault({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN // Only this token is needed, ephemeral
});

async function getSecret(path) {
  try {
    const result = await vaultClient.read(`secret/data/${path}`);
    return result.data.data;
  } catch (error) {
    console.error('Vault error:', error);
    throw error;
  }
}

// Usage
const dbConfig = await getSecret('production/database');
```

#### 4. **Secret Rotation Strategy**

```javascript
// Implement automatic secret rotation
class RotatingSecretManager {
  async getSecretWithRotation(secretName, maxAge = 24 * 60 * 60 * 1000) {
    const cachedSecret = this.cache.get(secretName);

    if (!cachedSecret || Date.now() - cachedSecret.timestamp > maxAge) {
      const freshSecret = await this.fetchSecret(secretName);
      this.cache.set(secretName, {
        value: freshSecret,
        timestamp: Date.now()
      });
      return freshSecret;
    }

    return cachedSecret.value;
  }
}
```

#### 5. **Runtime Secret Validation**

```javascript
// Validate secret quality at startup
const validateSecretStrength = {
  JWT_SECRET: (value) => value && value.length >= 32,
  DATABASE_URL: (value) => value && value.includes('://'),
  AWS_SECRET_ACCESS_KEY: (value) => value && value.length >= 16
};

function validateSecrets() {
  const secrets = Object.keys(validateSecretStrength);
  const invalid = secrets.filter(key => 
    !validateSecretStrength[key](process.env[key])
  );

  if (invalid.length > 0) {
    throw new Error(`Invalid secrets: ${invalid.join(', ')}`);
  }
}

validateSecrets();
```

