// aws-secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    throw new Error('Secret binary not supported');
  } catch (err) {
    if (err.code === 'ResourceNotFoundException') {
      console.warn(`⚠️  Secret not found: ${secretName}, falling back to process.env`);
      return null;
    }
    throw err;
  }
}

async function loadSecrets() {
  // Only load from AWS in production/staging
  if (['production', 'staging'].includes(process.env.NODE_ENV)) {
    console.log('🔐 Loading secrets from AWS Secrets Manager...');

    try {
      const dbSecrets = await getSecret('prod/app/database');
      const apiSecrets = await getSecret('prod/app/api-keys');

      // Merge with environment variables (AWS takes precedence)
      if (dbSecrets) {
        process.env.DATABASE_URL = dbSecrets.url;
        process.env.DB_USER = dbSecrets.username;
        process.env.DB_PASSWORD = dbSecrets.password;
      }

      if (apiSecrets) {
        process.env.ANTHROPIC_API_KEY = apiSecrets.anthropic;
        process.env.STRIPE_SECRET_KEY = apiSecrets.stripe;
        process.env.LOGFIRE_TOKEN = apiSecrets.logfire;
      }

      console.log('✅ Secrets loaded from AWS Secrets Manager');
    } catch (err) {
      console.error('❌ Failed to load secrets from AWS:', err.message);
      throw err;
    }
  }
}

module.exports = { getSecret, loadSecrets };
```

