// app.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretCache = {}; // Simple in-memory cache with TTL

async function getSecret(secretName) {
  // Check cache first
  if (secretCache[secretName] && Date.now() - secretCache[secretName].timestamp < 300000) {
    return secretCache[secretName].value;
  }

  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    const response = await client.send(new GetSecretValueCommand({ SecretId: secretName }));

    const secret = response.SecretString;
    const parsedSecret = secret ? JSON.parse(secret) : {};

    // Cache for 5 minutes
    secretCache[secretName] = {
      value: parsedSecret,
      timestamp: Date.now()
    };

    return parsedSecret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw new Error('Failed to retrieve configuration');
  }
}

