// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });
    this.cachedSecrets = {};
  }

  async getSecret(secretName) {
    // Check cache first (with TTL)
    if (this.cachedSecrets[secretName]?.value) {
      const { value, timestamp } = this.cachedSecrets[secretName];
      const age = Date.now() - timestamp;

      // Cache for 5 minutes to reduce AWS API calls
      if (age < 5 * 60 * 1000) {
        return value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      const secret = response.SecretString ? JSON.parse(response.SecretString) : null;

      // Cache the result
      this.cachedSecrets[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secret not found: ${secretName}`);
    }
  }
}

// Usage in app.js
