// middleware/validateSecrets.js
class SecretsValidator {
  static getRequiredSecrets() {
    // Different secrets for different environments
    const secretsByEnv = {
      production: [
        'DATABASE_URL',
        'AWS_SECRET_ACCESS_KEY',
        'STRIPE_SECRET_KEY'
      ],
      development: [],
      test: []
    };

    const env = process.env.NODE_ENV || 'development';
    return secretsByEnv[env] || secretsByEnv.development;
  }

  static validate() {
    const required = this.getRequiredSecrets();
    const missing = [];

    for (const secret of required) {
      if (!process.env[secret]) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Configuration Error: Missing required secrets for ${process.env.NODE_ENV}: ` +
        missing.join(', ')
      );
    }

    return true;
  }

  // Sanitize logs to prevent secret leakage
  static sanitize(data) {
    const secretKeys = [
      'password', 'secret', 'token', 'key', 'access', 
      'authorization', 'credential', 'private'
    ];

    const sanitized = { ...data };

    for (const key of Object.keys(sanitized)) {
      const lowerKey = key.toLowerCase();
      if (secretKeys.some(secret => lowerKey.includes(secret))) {
        sanitized[key] = '[REDACTED]';
      }
    }

    return sanitized;
  }
}

module.exports = SecretsValidator;
