/**
 * AWS Secrets Manager Integration
 * Production-grade secrets management
 * 
 * Security Features:
 * - Encrypted secrets storage (AES-256 via AWS KMS)
 * - Automatic secret caching with TTL
 * - Secrets validation on startup
 * - Versioning support
 * - CloudTrail audit logging
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.secretId = options.secretId || process.env.SECRET_ARN;
    this.cacheTTL = options.cacheTTL || 5 * 60 * 1000; // 5 minutes default

    this.client = new SecretsManagerClient({ region: this.region });
    this.cache = null;
    this.cacheExpiry = null;
  }

  /**
   * Fetch secret from AWS Secrets Manager (with caching)
   * @returns {Promise<Object>} Secrets object
   */
  async getSecrets() {
    // Return cached secrets if still valid
    if (this._isCacheValid()) {
      return this.cache;
    }

    // Fetch from AWS Secrets Manager
    try {
      const response = await this._fetchFromSecretsManager();
      const secrets = JSON.parse(response.SecretString);

      // Cache the secrets
      this.cache = secrets;
      this.cacheExpiry = Date.now() + this.cacheTTL;

      return secrets;
    } catch (error) {
      console.error('Failed to fetch secrets from AWS Secrets Manager:', error.message);
      throw new Error(`Secrets retrieval failed: ${error.message}`);
    }
  }

  /**
   * Fetch secret from AWS Secrets Manager
   * @private
   */
  async _fetchFromSecretsManager() {
    if (!this.secretId) {
      throw new Error('SECRET_ARN environment variable is required');
    }

    const command = new GetSecretValueCommand({
      SecretId: this.secretId,
      VersionStage: 'AWSCURRENT' // Always get current version
    });

    const response = await this.client.send(command);

    if (!response.SecretString) {
      throw new Error('Secret returned empty SecretString');
    }

    return response;
  }

  /**
   * Check if cache is still valid
   * @private
   */
  _isCacheValid() {
    return this.cache && 
           this.cacheExpiry && 
           Date.now() < this.cacheExpiry;
  }

  /**
   * Clear the secrets cache (force next fetch)
   */
  clearCache() {
    this.cache = null;
    this.cacheExpiry = null;
  }

  /**
   * Get specific secret value
   * @param {string} path - Dot-notation path (e.g., 'database.url')
   * @returns {Promise<any>} Secret value
   */
  async getSecret(path) {
    const secrets = await this.getSecrets();
    return this._getNestedValue(secrets, path);
  }

  /**
   * Get nested object value by path
   * @private
   */
  _getNestedValue(obj, path) {
    return path.split('.').reduce((current, key) => {
      return current && current[key] !== undefined ? current[key] : undefined;
    }, obj);
  }

  /**
   * Validate that required secrets are present
   * @param {Array<string>} requiredPaths - Array of required secret paths
   * @throws {Error} If any required secret is missing
   */
  async validateRequired(requiredPaths) {
    const secrets = await this.getSecrets();
    const missing = [];

    for (const path of requiredPaths) {
      const value = this._getNestedValue(secrets, path);
      if (value === undefined || value === null || value === '') {
        missing.push(path);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        `Please configure them in AWS Secrets Manager: ${this.secretId}`
      );
    }
  }
}

/**
 * Development Mode Config (load from .env)
 * ONLY for local development - NEVER use in production
 */
class DevSecretsManager {
  constructor() {
    require('dotenv').config({ path: `.env.${process.env.NODE_ENV || 'development'}` });

    this._validateEnvFile();
  }

  _validateEnvFile() {
    // Check if .env file exists (should exist in dev only)
    const fs = require('fs');
    const path = require('path');
    const envFile = path.join(process.cwd(), `.env.${process.env.NODE_ENV || 'development'}`);

    if (!fs.existsSync(envFile)) {
      console.warn(`Warning: ${envFile} not found. Using environment variables directly.`);
    }
  }

  async getSecrets() {
    // NEVER log or expose actual secret values!
    return {
      database: {
        url: process.env.DATABASE_URL
      },
      stripe: {
        publishableKey: process.env.STRIPE_PUBLISHABLE_KEY,
        secretKey: process.env.STRIPE_SECRET_KEY
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION
      },
      anthropic: {
        apiKey: process.env.ANTHROPIC_API_KEY
      },
      logfire: {
        token: process.env.LOGFIRE_TOKEN
      },
      app: {
        jwtSecret: process.env.JWT_SECRET,
        sessionSecret: process.env.SESSION_SECRET
      }
    };
  }

  async getSecret(path) {
    const secrets = await this.getSecrets();
    const value = path.split('.').reduce((current, key) => {
      return current && current[key] !== undefined ? current[key] : undefined;
    }, secrets);

    if (value === undefined) {
      throw new Error(`Secret not found: ${path}`);
    }

    return value;
  }

  async validateRequired(requiredPaths) {
    const secrets = await this.getSecrets();
    const missing = [];

    for (const path of requiredPaths) {
      const value = path.split('.').reduce((current, key) => {
        return current && current[key] !== undefined ? current[key] : undefined;
      }, secrets);

      if (value === undefined || value === null || value === '') {
        missing.push(path);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        `Set them in .env file (NEVER commit .env to git)`
      );
    }
  }
}

/**
 * Factory function to get appropriate secrets manager
 * Uses AWS Secrets Manager in production, .env for development
 */
function getSecretsManager() {
  const isProduction = process.env.NODE_ENV === 'production';
  const isStaging = process.env.NODE_ENV === 'staging';

  // Always use real secrets manager in staging/production
  if (isProduction || isStaging) {
    return new SecretsManager();
  }

  // Dev mode: can use either AWS Secrets Manager or .env
  const useAwsInDev = process.env.USE_AWS_SECRETS_IN_DEV === 'true';
  if (useAwsInDev) {
    return new SecretsManager();
  }

  return new DevSecretsManager();
}

module.exports = {
  SecretsManager,
  DevSecretsManager,
  getSecretsManager
};

// Example usage:
/*
const { getSecretsManager } = require('./secrets-manager');

// Get secrets manager instance
const secrets = getSecretsManager();

// Validate required secrets on startup
await secrets.validateRequired([
  'database.url',
  'stripe.secretKey',
  'app.jwtSecret'
]);

// Use secrets in your app
const dbUrl = await secrets.getSecret('database.url');
const stripeKey = await secrets.getSecret('stripe.secretKey');
*/

/**
 * Application Configuration
 * Single source of truth for all application configuration
 * Loads secrets securely and validates on startup
 */

const { getSecretsManager } = require('./secrets-manager');

class Config {
  constructor() {
    this.secretsManager = getSecretsManager();
    this._config = null;
  }

  /**
   * Initialize and validate configuration
   * Call this at application startup
   */
  async init() {
    // Validate required secrets based on environment
    const requiredSecrets = this._getRequiredSecrets();
    await this.secretsManager.validateRequired(requiredSecrets);

    // Load all configuration
    await this._loadConfig();

    // Log that config loaded successfully (never log actual values!)
    console.log('✓ Configuration loaded successfully');

    return this;
  }

  /**
   * Get required secrets based on environment
   * @private
   */
  _getRequiredSecrets() {
    const isProduction = process.env.NODE_ENV === 'production';

    const baseSecrets = [
      'app.jwtSecret',
      'session.secret'
    ];

    const productionSecrets = [
      ...baseSecrets,
      'database.url',
      'stripe.secretKey'
    ];

    return isProduction ? productionSecrets : baseSecrets;
  }

  /**
   * Load all configuration from environment and secrets
   * @private
   */
  async _loadConfig() {
    const allSecrets = await this.secretsManager.getSecrets();

    this._config = {
      // Environment
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT, 10) || (process.env.NODE_ENV === 'production' ? 443 : 3000),

      // Application
      app: {
        name: process.env.APP_NAME || 'express-app',
        url: process.env.APP_URL || 'http://localhost:3000',
        logLevel: process.env.LOG_LEVEL || 'info'
      },

      // Database (from secrets manager)
      database: {
        url: allSecrets.database?.url || process.env.DATABASE_URL,
        poolMin: parseInt(process.env.DB_POOL_MIN, 10) || 2,
        poolMax: parseInt(process.env.DB_POOL_MAX, 10) || 10,
        connectionTimeout: 10000
      },

      // Security (from secrets manager)
      security: {
        jwt: {
          secret: allSecrets.app?.jwtSecret || process.env.JWT_SECRET,
          expiresIn: process.env.JWT_EXPIRES_IN || '1h'
        },
        session: {
          secret: allSecrets.session?.secret || process.env.SESSION_SECRET,
          maxAge: parseInt(process.env.SESSION_MAX_AGE, 10) || 24 * 60 * 60 * 1000
        },
        rateLimit: {
          windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 15 * 60 * 1000,
          maxRequests: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100
        },
        cors: {
          allowedOrigins: this._parseAllowedOrigins(process.env.ALLOWED_ORIGINS)
        }
      },

      // Stripe (from secrets manager)
      stripe: {
        publishableKey: allSecrets.stripe?.publishableKey || process.env.STRIPE_PUBLISHABLE_KEY,
        secretKey: allSecrets.stripe?.secretKey || process.env.STRIPE_SECRET_KEY,
        webhookSecret: process.env.STRIPE_WEBHOOK_SECRET
      },

      // AWS (from secrets manager)
      aws: {
        accessKeyId: allSecrets.aws?.accessKeyId || process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: allSecrets.aws?.secretAccessKey || process.env.AWS_SECRET_ACCESS_KEY,
        region: allSecrets.aws?.region || process.env.AWS_REGION || 'us-east-1',
        s3: {
          bucket: process.env.AWS_S3_BUCKET
        }
      },

      // External Services (from secrets manager)
      external: {
        anthropic: {
          apiKey: allSecrets.anthropic?.apiKey || process.env.ANTHROPIC_API_KEY
        },
        logfire: {
          token: allSecrets.logfire?.token || process.env.LOGFIRE_TOKEN
        }
      },

      // Features (feature flags)
      features: {
        enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false',
        enableRequestLogging: process.env.ENABLE_REQUEST_LOGGING !== 'false',
        enableDetailedErrors: process.env.NODE_ENV !== 'production',
        enableCache: process.env.ENABLE_CACHE !== 'false'
      },

      // SSL/TLS (production only)
      ssl: {
        enabled: process.env.NODE_ENV === 'production',
        keyPath: process.env.SSL_KEY_PATH,
        certPath: process.env.SSL_CERT_PATH,
        caPath: process.env.SSL_CA_PATH
      }
    };

    this._validateConfig();
  }

  /**
   * Parse allowed origins from comma-separated string
   * @private
   */
  _parseAllowedOrigins(originsString) {
    if (!originsString) {
      const defaults = process.env.NODE_ENV === 'production' 
        ? [] 
        : ['http://localhost:3000', 'http://localhost:3001'];
      return defaults;
    }
    return originsString.split(',').map(origin => origin.trim());
  }

  /**
   * Validate configuration values
   * @private
   */
  _validateConfig() {
    const errors = [];

    // Check required port is number
    if (isNaN(this._config.port)) {
      errors.push('PORT must be a valid number');
    }

    // Check production-specific requirements
    if (this._config.env === 'production') {
      if (!this._config.security.jwt.secret || this._config.security.jwt.secret.length < 32) {
        errors.push('JWT_SECRET must be at least 32 characters in production');
      }

      if (!this._config.security.session.secret || this._config.security.session.secret.length < 32) {
        errors.push('SESSION_SECRET must be at least 32 characters in production');
      }

      if (this._config.ssl.enabled) {
        if (!this._config.ssl.keyPath || !this._config.ssl.certPath) {
          errors.push('SSL_KEY_PATH and SSL_CERT_PATH required in production');
        }
      }
    }

    if (errors.length > 0) {
      throw new Error(`Configuration validation failed:\n${errors.join('\n')}`);
    }
  }

  /**
   * Get configuration value
   * Supports dot notation: config.get('database.url')
   */
  get(path) {
    if (!this._config) {
      throw new Error('Config not initialized. Call config.init() first.');
    }

    return this._getNestedValue(this._config, path);
  }

  /**
   * Get nested object value by path
   * @private
   */
  _getNestedValue(obj, path) {
    return path.split('.').reduce((current, key) => {
      return current && current[key] !== undefined ? current[key] : undefined;
    }, obj);
  }

  /**
   * Check if running in production
   */
  isProduction() {
    return this._config?.env === 'production';
  }

  /**
   * Check if running in development
   */
  isDevelopment() {
    return this._config?.env === 'development';
  }

  /**
   * Check if running in staging
   */
  isStaging() {
    return this._config?.env === 'staging';
  }

  /**
   * Get entire config object (use with caution!)
   * NEVER log the returned object as it contains secrets
   */
  getAll() {
    if (!this._config) {
      throw new Error('Config not initialized. Call config.init() first.');
    }
    return this._config;
  }

  /**
   * Get safe config object for logging (secrets removed)
   */
  getSafeConfig() {
    if (!this._config) {
      throw new Error('Config not initialized. Call config.init() first.');
    }

    const safe = JSON.parse(JSON.stringify(this._config));

    // Remove sensitive values
    if (safe.database?.url) {
      safe.database.url = '[REDACTED]';
    }
    if (safe.security?.jwt?.secret) {
      safe.security.jwt.secret = '[REDACTED]';
    }
    if (safe.security?.session?.secret) {
      safe.security.session.secret = '[REDACTED]';
    }
    if (safe.stripe?.secretKey) {
      safe.stripe.secretKey = '[REDACTED]';
    }
    if (safe.aws?.secretAccessKey) {
      safe.aws.secretAccessKey = '[REDACTED]';
    }
    if (safe.aws?.accessKeyId) {
      safe.aws.accessKeyId = '[REDACTED]';
    }
    if (safe.external?.anthropic?.apiKey) {
      safe.external.anthropic.apiKey = '[REDACTED]';
    }
    if (safe.external?.logfire?.token) {
      safe.external.logfire.token = '[REDACTED]';
    }

    return safe;
  }
}

// Export singleton instance
