/**
 * SECURE APPLICATION BOOTSTRAP
 * 
 * This file demonstrates the PROPER way to bootstrap a secure Express application
 * with secrets management from AWS Secrets Manager.
 * 
 * DO NOT use dotenv directly in production!
 */

require('dotenv').config(); // OK - this just sets process.env, not loading secrets

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Import our secure config module
const config = require('./config');

/**
 * Application bootstrap with secure config loading
 */
async function bootstrapApp() {
  console.log('🚀 Starting secure application...');
  console.log(`📍 Environment: ${process.env.NODE_ENV || 'development'}`);

  try {
    // 1. Initialize configuration (loads from AWS Secrets Manager in production)
    // This validates that all required secrets are available
    await config.init();

    console.log('✓ Configuration loaded and validated');

    // 2. Create Express app
    const app = express();

    // 3. Apply security middleware
    applySecurityMiddleware(app);

    // 4. Apply rate limiting
    applyRateLimiting(app);

    // 5. Setup logging
    setupLogging(app);

    // 6. Setup request ID
    setupRequestId(app);

    // 7. Apply HTTP method restrictions
    applyMethodRestrictions(app);

    // 8. Define routes
    setupRoutes(app);

    // 9. Setup error handling
    setupErrorHandling(app);

    // 10. Start server
    startServer(app);

  } catch (error) {
    console.error('❌ Failed to start application:', error.message);
    console.error(error.stack);
    process.exit(1);
  }
}

/**
 * Apply security middleware (Helmet)
 */
function applySecurityMiddleware(app) {
  app.use(helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        scriptSrc: ["'self'"],
        imgSrc: ["'self'", "data:", "https:"],
      },
    },
    hsts: {
      maxAge: 31536000,
      includeSubDomains: true,
      preload: true
    },
  }));
  console.log('✓ Security headers applied');
}

/**
 * Apply rate limiting
 */
function applyRateLimiting(app) {
  const windowMs = config.get('security.rateLimit.windowMs');
  const maxRequests = config.get('security.rateLimit.maxRequests');

  const limiter = rateLimit({
    windowMs,
    max: maxRequests,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try again later.' },
    skip: (req) => {
      // Skip rate limiting for health checks
      return req.path === '/health';
    }
  });

  if (config.get('features.enableRateLimiting')) {
    app.use(limiter);
    console.log(`✓ Rate limiting applied: ${maxRequests} requests per ${windowMs}ms`);
  }
}

/**
 * Setup logging
 */
function setupLogging(app) {
  if (!config.get('features.enableRequestLogging')) {
    console.log('⏭ Request logging disabled');
    return;
  }

  const logDir = path.join(__dirname, 'logs');
  if (!fs.existsSync(logDir)) {
    fs.mkdirSync(logDir, { mode: 0o700 });
  }

  const accessLogStream = fs.createWriteStream(
    path.join(logDir, 'access.log'),
    { flags: 'a', mode: 0o600 }
  );

  morgan.token('request-id', (req) => req.id);
  const logFormat = ':request-id [:date[clf]] ":method :url" :status :res[content-length] ":referrer" ":user-agent"';

  app.use(morgan(logFormat, { 
    stream: accessLogStream,
    skip: (req) => req.path === '/health'
  }));

  if (config.isDevelopment()) {
    app.use(morgan('dev'));
  }

  console.log('✓ Logging configured');
}

/**
 * Setup request IDs for tracing
 */
function setupRequestId(app) {
  app.use((req, res, next) => {
    req.id = crypto.randomBytes(16).toString('hex');
    res.setHeader('X-Request-ID', req.id);
    next();
  });
  console.log('✓ Request ID tracking enabled');
}

/**
 * Apply HTTP method restrictions
 */
function applyMethodRestrictions(app) {
  const ALLOWED_METHODS = ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS', 'HEAD'];
  app.use((req, res, next) => {
    if (!ALLOWED_METHODS.includes(req.method.toUpperCase())) {
      res.setHeader('Allow', ALLOWED_METHODS.join(', '));
      return res.status(405).json({ 
        error: 'Method Not Allowed',
        requestId: req.id
      });
    }
    next();
  });
  console.log('✓ HTTP method restrictions applied');
}

/**
 * Validation middleware
 */
function validateRequest(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array(),
      requestId: req.id
    });
  }
  next();
}

/**
 * Output sanitization
 */
function sanitizeUser(user) {
  const { email, ...sanitized } = user;
  return {
    ...sanitized,
    email: `${email[0]}***@${email.split('@')[1]}`
  };
}

/**
 * Setup application routes
 */
function setupRoutes(app) {
  // Health check
  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      requestId: req.id,
      environment: config.get('env')
    });
  });

  // Users endpoint with validation
  app.get('/users',
    [
      query('id').optional().isInt({ min: 1 }).toInt(),
      query('email').optional().isEmail().normalizeEmail().trim(),
      query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
      query('page').optional().isInt({ min: 1 }).toInt()
    ],
    validateRequest,
    (req, res) => {
      // Mock user data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply filters
      let filteredUsers = users;

      if (req.query.id) {
        filteredUsers = filteredUsers.filter(u => u.id === req.query.id);
      }

      if (req.query.email) {
        filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
      }

      // Apply pagination
      const limit = req.query.limit || 10;
      const page = req.query.page || 1;
      const start = (page - 1) * limit;
      const paginatedUsers = filteredUsers.slice(start, start + limit);

      // Sanitize output
      res.json({
        data: paginatedUsers.map(sanitizeUser),
        meta: {
          total: filteredUsers.length,
          page,
          limit,
          requestId: req.id
        }
      });
    }
  );

  // Config info endpoint (demonstrates safe config usage)
  app.get('/config/info', (req, res) => {
