      },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );

    logger.info({ type: 'LOGIN_SUCCESS', username: username });

    res.json({ 
      token,
      user: {
        id: user.id,
        username: user.username,
        permissions: user.permissions
      }
    });
  } catch (error) {
    logger.error({ type: 'LOGIN_ERROR', error: error.message });
