    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  validateRequest
], (req, res) => {
  // In a real app, fetch from database with pagination
  const sanitizedUsers = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json(sanitizedUsers);
});

// Create user endpoint
app.post('/users', authenticateToken, authorize(['write:users']), [
  body('name')
    .trim()
    .isLength({ min: 2, max: 100 })
    .escape()
    .matches(/^[a-zA-Z\s]+$/)
    .withMessage('Name must contain only letters and spaces'),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
  validateRequest
], (req, res) => {
  const { name, email } = req.body;

  // In a real app, create user in database
  logger.info({ type: 'USER_CREATED', user: { name, email }, createdBy: req.user.userId });

  res.status(201).json({ 
    message: 'User created', 
    user: { id: Date.now(), name, email } 
  });
});

// Logout endpoint (client-side token invalidation recommended)
app.post('/logout', authenticateToken, (req, res) => {
  logger.info({ type: 'LOGOUT', userId: req.user.userId });
  res.json({ message: 'Logged out successfully' });
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  logger.warn({
    type: 'NOT_FOUND',
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const isDevelopment = NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal server error',
