/**
 * Security Test Script
 * Tests common security vulnerabilities in Express applications
 * Run with: node test-security.js
 */

const http = require('http');

const BASE_URL = process.env.TEST_URL || 'http://localhost:3000';

// ANSI color codes
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m'
};

let passed = 0;
let failed = 0;
let warnings = 0;

function log(message, color = 'reset') {
  console.log(`${colors[color]}${message}${colors.reset}`);
}

function makeRequest(url, method = 'GET', headers = {}) {
  return new Promise((resolve, reject) => {
    const urlObj = new URL(url);
    const options = {
      hostname: urlObj.hostname,
      port: urlObj.port || 3000,
      path: urlObj.pathname + urlObj.search,
      method: method,
      headers: headers
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({
        statusCode: res.statusCode,
        headers: res.headers,
        body: data
      }));
    });

    req.on('error', reject);
    if (method === 'POST') {
      req.write(JSON.stringify(headers.body));
    }
    req.end();
  });
}

async function testSecurityHeaders() {
  log('\n🔒 Testing Security Headers...', 'blue');

  try {
    const response = await makeRequest(`${BASE_URL}/health`);

    const requiredHeaders = {
      'x-frame-options': 'Clickjacking protection',
      'x-content-type-options': 'MIME sniffing protection',
      'strict-transport-security': 'HTTPS enforcement',
      'content-security-policy': 'XSS protection',
      'x-xss-protection': 'XSS filter',
      'referrer-policy': 'Referrer information'
    };

    for (const [header, description] of Object.entries(requiredHeaders)) {
      const value = response.headers[header] || response.headers[header.toUpperCase()];
      if (value) {
        log(`✓ ${header}: ${value}`, 'green');
        passed++;
      } else {
        log(`✗ Missing ${header} (${description})`, 'red');
        failed++;
      }
    }
  } catch (error) {
    log(`✗ Failed to test security headers: ${error.message}`, 'red');
    failed++;
  }
}

async function testAuthentication() {
  log('\n🔐 Testing Authentication...', 'blue');

  try {
    // Test unauthenticated access to /users
    const response = await makeRequest(`${BASE_URL}/users`);

    if (response.statusCode === 401 || response.statusCode === 403) {
      log('✓ /users endpoint requires authentication', 'green');
      passed++;
    } else if (response.statusCode === 200) {
      log('✗ /users endpoint is publicly accessible without authentication', 'red');
      failed++;
    }
  } catch (error) {
    log(`✗ Failed to test authentication: ${error.message}`, 'red');
    failed++;
  }
}

async function testRateLimiting() {
  log('\n⚡ Testing Rate Limiting...', 'blue');

  try {
    let maxStatusCode = 200;
    const testRequests = 15;

    for (let i = 0; i < testRequests; i++) {
      try {
        const response = await makeRequest(`${BASE_URL}/health`);
        maxStatusCode = Math.max(maxStatusCode, response.statusCode);

        if (response.statusCode === 429) {
          log(`✓ Rate limiting triggered after ${i + 1} requests`, 'green');
          passed++;
          break;
        }
      } catch (error) {
        // Request failed, might be rate limited
        maxStatusCode = 429;
      }
    }

    if (maxStatusCode !== 429) {
      log(`⚠ Rate limiting not detected after ${testRequests} requests`, 'yellow');
      warnings++;
      passed++;
    }
  } catch (error) {
    log(`⚠ Could not test rate limiting: ${error.message}`, 'yellow');
    warnings++;
  }
}

async function testInformationDisclosure() {
  log('\n📊 Testing Information Disclosure...', 'blue');

  try {
    const response = await makeRequest(`${BASE_URL}/health`);
    const body = JSON.parse(response.body || '{}');

    // Check for sensitive information exposure
    const sensitiveFields = ['stack', 'error', 'env', 'servername', 'timestamp'];
    let exposed = [];

    for (const field of sensitiveFields) {
      if (field in body) {
        exposed.push(field);
      }
    }

    if (exposed.length === 0) {
      log('✓ No sensitive information exposed in health endpoint', 'green');
      passed++;
    } else {
      log(`⚠ Potential information disclosure: ${exposed.join(', ')}`, 'yellow');
      warnings++;
    }

    // Check response headers for server information
    const server = response.headers['server'];
    if (!server || server === 'nginx') {
      log('✓ Server information not disclosed or properly masked', 'green');
      passed++;
    } else {
      log(`⚠ Server header disclosed: ${server}`, 'yellow');
      warnings++;
    }
  } catch (error) {
    log(`⚠ Could not test information disclosure: ${error.message}`, 'yellow');
    warnings++;
  }
}

async function testCORSPolicy() {
  log('\n🌐 Testing CORS Policy...', 'blue');

  try {
    const response = await makeRequest(`${BASE_URL}/users`, 'GET', {
      'Origin': 'http://malicious-site.com'
    });

    const corsHeader = response.headers['access-control-allow-origin'];

    if (corsHeader === '*') {
      log('⚠ CORS allows all origins (consider restricting)', 'yellow');
      warnings++;
    } else if (corsHeader && corsHeader !== 'http://malicious-site.com') {
      log(`✓ CORS properly restricted to: ${corsHeader}`, 'green');
      passed++;
    } else if (!corsHeader) {
      log('✓ No CORS header (CORS not configured)', 'yellow');
      warnings++;
    }
  } catch (error) {
    log(`⚠ Could not test CORS: ${error.message}`, 'yellow');
    warnings++;
  }
}

async function testInputValidation() {
  log('\n✅ Testing Input Validation...', 'blue');

  try {
    // Test malicious input
    const maliciousPayloads = [
      '<script>alert("xss")</script>',
      "' OR '1'='1",
      '../../../etc/passwd'
    ];

    let allValidated = true;

    for (const payload of maliciousPayloads) {
      try {
        const response = await makeRequest(`${BASE_URL}/users?name=${encodeURIComponent(payload)}`);

        // If we get a 400 or 422, validation is working
        if (response.statusCode === 400 || response.statusCode === 422) {
          log(`✓ Malicious payload rejected: ${payload.substring(0, 30)}...`, 'green');
        } else {
          log(`⚠ Payload accepted (may need validation): ${payload.substring(0, 30)}...`, 'yellow');
          allValidated = false;
        }
      } catch (error) {
        // Request failed
      }
    }

    if (allValidated) {
      log('✓ Input validation appears to be working', 'green');
      passed++;
    } else {
      log('⚠ Some payloads accepted (review input validation)', 'yellow');
      warnings++;
      passed++;
    }
  } catch (error) {
    log(`⚠ Could not test input validation: ${error.message}`, 'yellow');
    warnings++;
  }
}

async function testMethods() {
  log('\n📬 Testing HTTP Methods...', 'blue');

  const methods = ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'];
  const endpoint = '/health';

  for (const method of methods) {
    try {
      const response = await makeRequest(`${BASE_URL}${endpoint}`, method);

      // Check if HEAD is supported (should be for GET endpoints)
      if (method === 'GET') {
        log(`✓ ${method} ${endpoint} -> ${response.statusCode}`, 'green');
      } else if (response.statusCode === 405) {
        log(`✓ ${method} ${endpoint} -> 405 Method Not Allowed`, 'green');
      } else if (response.statusCode !== 404) {
        log(`ℹ ${method} ${endpoint} -> ${response.statusCode}`, 'blue');
      }
    } catch (error) {
      // Request failed
    }
  }
  passed++;
}

async function runAllTests() {
  log('\n' + '='.repeat(50), 'magenta');
  log('🔍 Security Test Suite', 'magenta');
  log('='.repeat(50), 'magenta');
  log(`Testing: ${BASE_URL}`, 'blue');

  await testSecurityHeaders();
  await testAuthentication();
  await testRateLimiting();
  await testInformationDisclosure();
  await testCORSPolicy();
  await testInputValidation();
  await testMethods();

  // Print summary
  log('\n' + '='.repeat(50), 'magenta');
  log('📊 Test Summary', 'magenta');
  log('='.repeat(50), 'magenta');
  log(`✅ Passed: ${passed}`, 'green');
  log(`❌ Failed: ${failed}`, failed > 0 ? 'red' : 'reset');
  log(`⚠️  Warnings: ${warnings}`, warnings > 0 ? 'yellow' : 'reset');
  log('='.repeat(50), 'magenta');

  if (failed > 0) {
    log('\n❌ CRITICAL issues found. Please review and fix.', 'red');
    process.exit(1);
  } else if (warnings > 0) {
    log('\n⚠️  Issues found. Review and consider implementing recommendations.', 'yellow');
    process.exit(0);
  } else {
    log('\n✅ All critical security checks passed!', 'green');
    process.exit(0);
  }
}

// Run tests
runAllTests().catch(error => {
  log(`\n❌ Test suite error: ${error.message}`, 'red');
  process.exit(1);
});

