```javascript
const dotenv = require('dotenv');
const crypto = require('crypto');

class EncryptedSecrets {
  constructor() {
    dotenv.config();
    this.algorithm = 'aes-256-gcm';
    this.key = process.env.SECRETS_ENCRYPTION_KEY;
  }

  decrypt(encryptedText) {
    const [iv, authTag, encrypted] = encryptedText.split(':');
    const decipher = crypto.createDecipheriv(
      this.algorithm,
      Buffer.from(this.key, 'hex'),
      Buffer.from(iv, 'hex')
    );
    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    return decipher.update(encrypted, 'hex', 'utf8') + decipher.final('utf8');
  }

  getSecret(name) {
    const encrypted = process.env[name];
    if (!encrypted) {
      throw new Error(`Secret ${name} not found`);
    }
    return this.decrypt(encrypted);
  }
}

// Usage
const secrets = new EncryptedSecrets();
const jwtSecret = secrets.getSecret('ENCRYPTED_JWT_SECRET');
