// config/secrets.js - Production integration
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class ProductionSecrets {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheTtl = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTtl) {
        return cached.value;
      }
    }

    // Fetch from AWS
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await this.client.send(command);

    if ('SecretString' in response) {
      const secret = JSON.parse(response.SecretString);
      this.cache.set(secretName, { value: secret, timestamp: Date.now() });
      return secret;
    }

    throw new Error(`Secret ${secretName} not found`);
  }
}

module.exports = new ProductionSecrets();
