#!/usr/bin/env node

/**
 * AWS Secrets Manager Integration for Secure Express.js Application
 * 
 * This module provides production-ready secrets management using AWS Secrets Manager.
 * 
 * Features:
 * - Automatic secret caching with TTL
 * - Graceful fallback to environment variables (dev mode)
 * - Secret rotation support
 * - Comprehensive error handling
 * - Audit logging
 * 
 * Usage:
 *   const secrets = require('./secrets-aws-integration');
 *   await secrets.initialize();
 *   const jwtSecret = secrets.get('JWT_SECRET');
 */

const { SecretsManagerClient, GetSecretValueCommand, PutSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const winston = require('winston');

// Configure logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'logs/secrets.log' })
  ]
});

/**
 * SecretsManager class - Handles all secret operations
 */
class SecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.env = options.env || process.env.NODE_ENV || 'development';

    this.client = new SecretsManagerClient({ region: this.region });

    this.cache = new Map();
    this.cacheTtl = options.cacheTtl || 5 * 60 * 1000; // 5 minutes default
    this.initialized = false;

    this.secretPrefix = options.secretPrefix || `${this.env}/app`;
  }

  /**
   * Initialize the secrets manager
   * Loads secrets on startup and validates required secrets
   */
  async initialize(requiredSecrets = []) {
    try {
      logger.info('Initializing AWS Secrets Manager...', { env: this.env, region: this.region });

      // Load all secrets
      await this.loadAllSecrets();

      // Validate required secrets
      const missingSecrets = requiredSecrets.filter(secret => !this.has(secret));

      if (missingSecrets.length > 0) {
        const error = `Missing required secrets: ${missingSecrets.join(', ')}`;
        logger.error(error, { missing: missingSecrets });
        throw new Error(error);
      }

      this.initialized = true;
      logger.info('AWS Secrets Manager initialized successfully');

      return this;
    } catch (error) {
      logger.error('Failed to initialize AWS Secrets Manager', { error: error.message });

      // In development, allow fallback to environment variables
      if (this.env === 'development') {
        logger.warn('Falling back to environment variables in development mode');
        this.initialized = true;
        return this;
      }

      throw error;
    }
  }

  /**
   * Get a specific secret value
   * @param {string} key - Secret key name
   * @param {boolean} forceRefresh - Force refresh from AWS (bypass cache)
   * @returns {string} Secret value
   */
  get(key, forceRefresh = false) {
    // Check cache
    if (!forceRefresh && this.cache.has(key)) {
      const cached = this.cache.get(key);
      if (Date.now() - cached.timestamp < this.cacheTtl) {
        logger.debug(`Secret retrieved from cache: ${this.maskSecret(key)}`);
        return cached.value;
      }
    }

    // Try environment variables (for development)
    const envValue = process.env[key];
    if (envValue) {
      logger.debug(`Secret retrieved from environment variable: ${this.maskSecret(key)}`);
      this.cache.set(key, { value: envValue, timestamp: Date.now() });
      return envValue;
    }

    throw new Error(`Secret not found: ${key}`);
  }

  /**
   * Check if a secret exists
   * @param {string} key - Secret key name
   * @returns {boolean}
   */
  has(key) {
    if (this.cache.has(key)) {
      return true;
    }
    return key in process.env;
  }

  /**
   * Get multiple secrets at once
   * @param {string[]} keys - Array of secret key names
   * @returns {object} Object with secret key-value pairs
   */
  getMany(keys) {
    const result = {};
    const missing = [];

    for (const key of keys) {
      try {
        result[key] = this.get(key);
      } catch (error) {
        missing.push(key);
      }
    }

    if (missing.length > 0) {
      logger.warn('Some secrets are missing', { missing });
    }

    return result;
  }

  /**
   * Load a secret from AWS Secrets Manager
   * @param {string} secretName - Full secret name/path in AWS
   * @returns {object} Secret object
   */
  async loadSecretFromAWS(secretName) {
    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      if ('SecretString' in response) {
        const secretString = response.SecretString;

        // Try to parse as JSON, otherwise return as string
        try {
          return JSON.parse(secretString);
        } catch {
          return { value: secretString };
        }
      }

      if ('SecretBinary' in response) {
        return response.SecretBinary;
      }

      throw new Error('Secret has no value');
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        logger.warn(`Secret not found in AWS: ${secretName}`);
        return null;
      }
      logger.error(`Failed to load secret ${secretName}`, { error: error.message });
      throw error;
    }
  }

  /**
   * Load all secrets from AWS Secrets Manager
   * Expected secret structure in AWS:
   * {
   *   "JWT_SECRET": "...",
   *   "DATABASE_URL": "...",
   *   "AWS_SECRET_ACCESS_KEY": "..."
   * }
   */
  async loadAllSecrets() {
    const secretName = `${this.secretPrefix}/secrets`;

    try {
      const secrets = await this.loadSecretFromAWS(secretName);

      if (secrets) {
        // Cache all secrets
        const timestamp = Date.now();
        for (const [key, value] of Object.entries(secrets)) {
          this.cache.set(key, { value, timestamp });
        }

        logger.info(`Loaded ${Object.keys(secrets).length} secrets from AWS`, {
          secretName: this.maskSecret(secretName)
        });
      } else {
        logger.info(`No secrets found in AWS for: ${this.maskSecret(secretName)}`);
      }
    } catch (error) {
      logger.error('Failed to load secrets from AWS', { error: error.message });
      // Don't throw - allow fallback to environment variables
    }
  }

  /**
   * Update a secret in AWS Secrets Manager
   * @param {string} key - Secret key
   * @param {string} value - New secret value
   */
  async updateSecret(key, value) {
    const secretName = `${this.secretPrefix}/secrets`;

    try {
      // Load existing secrets
      const existing = await this.loadSecretFromAWS(secretName) || {};

      // Update the specific secret
      existing[key] = value;

      // Save back to AWS
      const command = new PutSecretValueCommand({
        SecretId: secretName,
        SecretString: JSON.stringify(existing)
      });

      await this.client.send(command);

      // Update cache
      this.cache.set(key, { value, timestamp: Date.now() });

      logger.info(`Secret updated successfully: ${this.maskSecret(key)}`);

      return true;
    } catch (error) {
      logger.error(`Failed to update secret ${key}`, { error: error.message });
      throw error;
    }
  }

  /**
   * Rotate a secret - generate new random value
   * @param {string} key - Secret key to rotate
   * @param {number} length - Length of new secret (default 32)
   * @returns {string} New secret value
   */
  async rotateSecret(key, length = 32) {
    const crypto = require('crypto');
    const newValue = crypto.randomBytes(length).toString('hex');

    await this.updateSecret(key, newValue);

    logger.info(`Secret rotated successfully: ${this.maskSecret(key)}`);

    return newValue;
  }

  /**
   * Clear the secrets cache
   */
  clearCache() {
    this.cache.clear();
    logger.info('Secrets cache cleared');
  }

  /**
   * Get cache statistics
   */
  getCacheStats() {
    const entries = Array.from(this.cache.entries());
    return {
      size: this.cache.size,
      entries: entries.map(([key, value]) => ({
        key: this.maskSecret(key),
        age: Date.now() - value.timestamp,
        ttl: this.cacheTtl
      }))
    };
  }

  /**
   * Mask sensitive parts of secret names/values for logging
   * @param {string} secret - Secret name or partially masked value
   * @returns {string} Masked secret
   */
  maskSecret(secret) {
    const str = String(secret);
    if (str.length <= 8) {
      return '***';
    }
    return str.substring(0, 4) + '***' + str.substring(str.length - 4);
  }

  /**
   * Health check for secrets manager
   */
  async healthCheck() {
    const stats = {
      initialized: this.initialized,
      connected: true,
      cacheSize: this.cache.size,
      environment: this.env,
      region: this.region
    };

    try {
      // Try to fetch a secret to verify connection
      await this.client.send(new GetSecretValueCommand({ 
        SecretId: `${this.secretPrefix}/test` 
      }));
      stats.testConnection = 'OK';
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        stats.testConnection = 'Secret not found (expected if test secret not created)';
      } else {
        stats.connected = false;
        stats.testConnection = `Error: ${error.message}`;
      }
    }

    return stats;
  }
}

// Create singleton instance
const secretsManager = new SecretsManager();

/**
 * Command-line interface for secrets management
 */
if (require.main === module) {
  const command = process.argv[2];
  const key = process.argv[3];

  async function runCLI() {
    switch (command) {
      case 'get':
        await secretsManager.initialize();
        console.log(secretsManager.get(key));
        break;

      case 'rotate':
        await secretsManager.initialize();
        const newValue = await secretsManager.rotateSecret(key);
        console.log(`Rotated ${key}:`, secretsManager.maskSecret(newValue));
        break;

      case 'stats':
        await secretsManager.initialize();
        console.log(JSON.stringify(secretsManager.getCacheStats(), null, 2));
        break;

      case 'health':
        const health = await secretsManager.healthCheck();
        console.log(JSON.stringify(health, null, 2));
        break;

      default:
        console.log('Usage: node secrets-aws-integration.js <command> [args]');
        console.log('Commands:');
        console.log('  get <key>           - Get a secret value');
        console.log('  rotate <key>        - Rotate a secret');
        console.log('  stats               - Show cache statistics');
        console.log('  health              - Health check');
    }
  }

  runCLI().catch(console.error);
}

module.exports = secretsManager;

# Terraform configuration for AWS Secrets Manager
# This creates secrets with proper IAM policies and rotation

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  backend "s3" {
    bucket         = "your-terraform-state-bucket"
    key            = "secrets-manager/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-state-lock"
  }
}

provider "aws" {
  region = var.aws_region
}

# Variable declarations
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev, staging, prod)"
  type        = string
  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "Environment must be dev, staging, or prod."
  }
}

variable "jwt_secret" {
  description = "JWT signing secret (generate with: openssl rand -base64 42)"
  type        = string
  sensitive   = true
}

variable "database_url" {
  description = "Database connection URL"
  type        = string
  sensitive   = true
}

variable "stripe_secret_key" {
  description = "Stripe API secret key"
  type        = string
  sensitive   = true
}

variable "aws_access_key_id" {
  description = "AWS access key ID for application"
  type        = string
  sensitive   = true
  default     = null
}

variable "aws_secret_access_key" {
  description = "AWS secret access key for application"
  type        = string
  sensitive   = true
  default     = null
}

variable "enable_rotation" {
  description = "Enable automatic secret rotation"
  type        = bool
  default     = true
}

# Local variables
locals {
  secret_prefix = "${var.environment}/app"
  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    Project     = "secure-express-app"
  }
}

# IAM Role for Lambda rotation function
resource "aws_iam_role" "rotation_lambda_role" {
  name = "${var.environment}-secrets-rotation-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for secret rotation
resource "aws_iam_role_policy" "rotation_lambda_policy" {
  name = "${var.environment}-secrets-rotation-policy"
  role = aws_iam_role.rotation_lambda_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetSecretValue",
          "secretsmanager:PutSecretValue",
          "secretsmanager:UpdateSecretVersionStage"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# Main application secrets
resource "aws_secretsmanager_secret" "app_secrets" {
  name = "${local.secret_prefix}/secrets"

  description = "Application secrets for ${var.environment} environment"

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "app_secrets_version" {
  secret_id = aws_secretsmanager_secret.app_secrets.id

  secret_string = jsonencode({
    JWT_SECRET          = var.jwt_secret
    DATABASE_URL        = var.database_url
    STRIPE_SECRET_KEY   = var.stripe_secret_key
    AWS_ACCESS_KEY_ID   = var.aws_access_key_id
    AWS_SECRET_ACCESS_KEY = var.aws_secret_access_key
  })
}

# Secret rotation (optional, requires Lambda function)
resource "aws_lambda_function" "secret_rotation" {
  count = var.enable_rotation ? 1 : 0

  function_name = "${var.environment}-secrets-rotation"
  role          = aws_iam_role.rotation_lambda_role.arn
