  filename = data.archive_file.lambda_zip[count.index].output_path
  source_code_hash = data.archive_file.lambda_zip[count.index].output_base64sha256

  environment {
    variables = {
      SECRETS_MANAGER_ARN = aws_secretsmanager_secret.app_secrets.arn
    }
  }

  tags = local.tags
}

# Lambda ZIP archive (placeholder - you'd need actual rotation code)
data "archive_file" "lambda_zip" {
  count = var.enable_rotation ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/lambda_function.zip"

  source {
