}

# CloudWatch Logs for Lambda
resource "aws_cloudwatch_log_group" "lambda_logs" {
  count = var.enable_rotation ? 1 : 0

  name              = "/aws/lambda/${var.environment}-secrets-rotation"
  retention_in_days = 14

  tags = local.tags
}

# IAM Policy for application to access secrets
resource "aws_iam_policy" "app_secrets_access" {
  name        = "${var.environment}-app-secrets-access"
  description = "Policy for application to access its secrets"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AccessAppSecrets"
