// Using AWS Secrets Manager
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

 async function getSecret(secretName) {
  const client = new SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    const response = await client.getSecretValue({ SecretId: secretName });
    return JSON.parse(response.SecretString);
  } catch (error) {
    throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
  }
}

// Initialize on startup
async function initializeApp() {
  try {
    const secrets = await getSecret('myapp/production');

    // Apply secrets to environment
    process.env.DATABASE_URL = secrets.database_url;
    process.env.STRIPE_SECRET_KEY = secrets.stripe_secret_key;

    // Start application
    app.listen(3000, () => {
      console.log('Server started with secrets from AWS Secrets Manager');
    });
  } catch (error) {
    console.error('Failed to initialize:', error);
    process.exit(1);
  }
}

if (process.env.NODE_ENV === 'production') {
  initializeApp();
} else {
  // Use dotenv for local development
  require('dotenv').config();
  app.listen(3000, () => console.log('Server started in development mode'));
}
