// secrets-manager.js
const {
  SecretsManagerClient,
  GetSecretValueCommand
} = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    // Only initialize in production or if FORCE_SECRETS_MANAGER is set
    if (process.env.NODE_ENV === 'production' || process.env.FORCE_SECRETS_MANAGER) {
      this.client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1'
      });
      this.enabled = true;
    } else {
      this.enabled = false;
    }
  }

  async getSecret(secretName, fallback = null) {
    // In non-production, fall back to environment variables
    if (!this.enabled) {
      return process.env[secretName] || fallback;
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      if ('SecretString' in response) {
        const secret = JSON.parse(response.SecretString);
        return secret[secretName] || secret.value || fallback;
      }

      return fallback;
    } catch (error) {
      // Fail securely - don't crash if secret manager is unavailable
      console.error(`Failed to fetch secret ${secretName} from Secrets Manager:`, error.message);
      return process.env[secretName] || fallback;
    }
  }
}

