### Option 2: AWS Secrets Manager (Production-Grade)

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes
let cacheExpiry = 0;

async function loadSecrets() {
  // Return cached secrets if fresh
  if (cachedSecrets && Date.now() < cacheExpiry) {
    return cachedSecrets;
  }

  try {
    // For local development, use environment variables
    if (process.env.NODE_ENV === 'development' && !process.env.USE_AWS_SECRETS) {
      cachedSecrets = {
        databaseUrl: process.env.DATABASE_URL,
        sessionSecret: process.env.SESSION_SECRET,
        awsKeyId: process.env.AWS_ACCESS_KEY_ID,
        awsSecretKey: process.env.AWS_SECRET_ACCESS_KEY,
      };
      cacheExpiry = Date.now() + CACHE_TTL;
      return cachedSecrets;
    }

    // Production: fetch from AWS Secrets Manager
    const command = new GetSecretValueCommand({
      SecretId: process.env.SECRETS_ARN || 'myapp/production',
    });

    const response = await secretsClient.send(command);
    cachedSecrets = JSON.parse(response.SecretString);
    cacheExpiry = Date.now() + CACHE_TTL;

    return cachedSecrets;
  } catch (error) {
    console.error('Failed to load secrets:', error.message);
    throw new Error('Cannot initialize application: secrets unavailable');
  }
}

function getSecret(key) {
  if (!cachedSecrets) {
    throw new Error('Secrets not loaded. Call loadSecrets() first.');
  }
  return cachedSecrets[key];
}

module.exports = { loadSecrets, getSecret };
```

