## 📋 Secrets Management Best Practices

### 1. Never Commit .env Files

```gitignore
# .gitignore
.env
.env.*
!.env.example
*.key
*.pem
credentials/
secrets/
*.secrets.json
```

### 2. Use .env.example as Template

```bash
# .env.example - Safe to commit
# Database
DATABASE_URL=postgres://user:password@host:5432/database

# Security
SESSION_SECRET=

# AWS (only for local dev)
AWS_ACCESS_KEY_ID=
AWS_SECRET_ACCESS_KEY=
AWS_REGION=us-east-1

# Feature Flags
USE_AWS_SECRETS=false
```

### 3. Environment-Specific Loading

```javascript
// config/env.js
const dotenv = require('dotenv');

switch (process.env.NODE_ENV) {
  case 'production':
    // Production: No .env file - use actual environment variables
    // or fetch from secrets manager
    break;
  case 'test':
    // Test: Load .env.test
    dotenv.config({ path: '.env.test' });
    break;
  case 'development':
  default:
    // Development: Load .env.local
    dotenv.config({ path: '.env.local' });
    break;
}

module.exports = {
  isDevelopment: process.env.NODE_ENV === 'development',
  isProduction: process.env.NODE_ENV === 'production',
  isTest: process.env.NODE_ENV === 'test',
};
```

### 4. Secret Rotation Strategy

```javascript
// Support secret rotation with graceful degradation
class SecretManager {
  constructor() {
    this.secrets = {};
    this.lastRotate = null;
  }

  async load() {
    // Primary source
    try {
      this.secrets = await this.fetchFromSecretsManager();
      this.lastRotate = Date.now();
    } catch (primaryError) {
      // Fallback to environment variables for backup
      this.secrets = {
        databaseUrl: process.env.DATABASE_URL,
        sessionSecret: process.env.SESSION_SECRET,
      };
      console.warn('Using fallback secrets from environment');
    }

    this.validateRequiredSecrets();
  }

  async rotate() {
    try {
      await this.load();
      console.log('Secrets rotated successfully');
    } catch (error) {
      console.error('Secret rotation failed:', error.message);
    }
  }

  get(key) {
    return this.secrets[key];
  }

  validateRequiredSecrets() {
    const required = ['databaseUrl', 'sessionSecret'];
    const missing = required.filter(k => !this.secrets[k]);

    if (missing.length > 0) {
      throw new Error(`Missing secrets: ${missing.join(', ')}`);
    }
  }
}

module.exports = SecretManager;
