// config/secrets.js
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManager({ region: process.env.AWS_REGION });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    const cached = this.cache.get(secretName);

    if (!forceRefresh && cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretName
      });

      const secret = JSON.parse(response.SecretString);

      this.cache.set(secretName, {
        value: secret,
        expiresAt: Date.now() + this.cacheTimeout
      });

      return secret;
    } catch (error) {
      console.error(`SecretsManager error for ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret(process.env.DB_SECRET_NAME || 'prod/database');
  }

  async getStripeSecretKey() {
    const secret = await this.getSecret(
      process.env.STRIPE_SECRET_NAME || 'prod/stripe'
    );
    return secret.secretKey;
  }

  async getAWSCredentials() {
    return this.getSecret(
      process.env.AWS_CREDENTIALS_SECRET_NAME || 'prod/aws/credentials'
    );
  }
}

module.exports = SecretsManager;
