  constructor() {
    this.secrets = {};
    this.secretsManager = new SecretsManagerClient({ region: process.env.AWS_REGION });
  }

  async loadFromAWS(secretName) {
    try {
      const response = await this.secretsManager.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      if ('SecretBinary' in response) {
        return Buffer.from(response.SecretBinary, 'base64').toString();
      } else {
