// secrets.js - Centralized secrets management
const AWS = require('aws-sdk');
const { parse } = require('dotenv');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loaded = false;
  }

  async load() {
    if (this.loaded) return this.secrets;

    // Priority: Environment > Secrets Manager > .env (dev only)
    if (process.env.NODE_ENV === 'production' || process.env.AWS_EXECUTION_ENV) {
      await this.loadFromAWS();
    } else {
      this.loadFromDotEnv();
    }

    this.validate();
    this.loaded = true;
    return this.secrets;
  }

  async loadFromAWS() {
    const client = new AWS.SecretsManager();
    try {
      const data = await client.getSecretValue({ 
        SecretId: process.env.SECRET_NAME || 'prod/app-secrets' 
      }).promise();
      this.secrets = JSON.parse(data.SecretString);
    } catch (error) {
      console.error('Failed to load from AWS Secrets Manager:', error);
      throw error;
    }
  }

  loadFromDotEnv() {
    try {
      require('dotenv').config();
      this.secrets = {
