### 7. **Missing Request Timeout (DoS Protection)**

**Issue:** No request timeout configured, allowing slow attacks or hung connections.

**Recommendation:**
```javascript
// Set server-level timeout
const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

server.setTimeout(120000); // 2 minute timeout

// Or use middleware timeout
const timeout = require('connect-timeout');
app.use(timeout('5s'));
app.use/haltOnTimedout = (req, res, next) => {
  if (!req.timedout) next();
};

app.get('/users', (req, res) => {
  // Long-running operation check
  if (req.timedout) return;
  res.json([/*...*/]);
});
```

