// config/secrets.js
const dotenv = require('dotenv');
const path = require('path');

// Load environment-specific .env file
const env = process.env.NODE_ENV || 'development';
const envFile = path.resolve(process.cwd(), `.env.${env}`);

// Check if .env file exists (fail gracefully)
try {
  const result = dotenv.config({ path: envFile });

  if (result.error) {
    console.warn(`⚠️  Warning: Could not load ${envFile}`);
    console.warn(`   Server will rely on environment variables from the platform`);
  } else {
    console.log(`✅ Loaded configuration from ${envFile}`);
  }
} catch (err) {
  console.error(`❌ Error loading secrets: ${err.message}`);
}

// Validate required secrets exist
const requiredSecrets = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY'
];

const missingSecrets = requiredSecrets.filter(secret => !process.env[secret]);

if (missingSecrets.length > 0) {
  const errorMsg = `❌ Missing required environment variables: ${missingSecrets.join(', ')}`;

  // In production, fail fast. In development, warn but continue
  if (process.env.NODE_ENV === 'production') {
    throw new Error(errorMsg);
  } else {
    console.warn(`⚠️  ${errorMsg}`);
    console.warn(`   Some features may not work correctly.`);
  }
}

// Export validated secrets (never log these!)
module.exports = {
  database: {
    url: process.env.DATABASE_URL,
  },
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
