#### **PRODUCTION SECRETS MANAGER OPTIONS**

**RECOMMENDED: Use a proper secrets manager instead of .env files:**

---

**Option 1: AWS Secrets Manager (Recommended for AWS deployments)**
```javascript
// config/aws-secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function loadSecrets() {
  if (process.env.NODE_ENV !== 'production') {
    console.log('⚠️  Not in production, skipping AWS Secrets Manager');
    return {};
  }

  try {
    const secretName = process.env.SECRETS_MANAGER_NAME || 'myapp/production';
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      const secrets = JSON.parse(data.SecretString);
      Object.assign(process.env, secrets);
      console.log('✅ Loaded secrets from AWS Secrets Manager');
      return secrets;
    }
  } catch (err) {
    console.error('❌ Failed to load secrets from AWS Secrets Manager:', err.message);
    throw err;
  }
}

module.exports = { loadSecrets };
```

**Usage in app.js:**
```javascript
const { loadSecrets } = require('./config/aws-secrets-manager');

async function startServer() {
  await loadSecrets();
  require('./config/secrets'); // Load dotenv as fallback

  // Start app
