// config/vault.js
const axios = require('axios');

async function loadFromVault() {
  const vaultUrl = process.env.VAULT_ADDR || 'http://localhost:8200';
  const vaultToken = process.env.VAULT_TOKEN;
  const secretPath = process.env.VAULT_SECRET_PATH || 'secret/data/myapp';

  try {
    const response = await axios.get(
      `${vaultUrl}/v1/${secretPath}`,
      { headers: { 'X-Vault-Token': vaultToken } }
    );

    const secrets = response.data.data.data;
    Object.assign(process.env, secrets);
    console.log('✅ Loaded secrets from Vault');
    return secrets;
  } catch (err) {
    console.error('❌ Failed to load secrets from Vault:', err.message);
    throw err;
  }
}
