const AWS = require('aws-sdk');
const { v4: uuidv4 } = require('uuid');

// Local development: use .env
// Production: fetch from AWS Secrets Manager

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
    this.lastFetch = 0;
  }

  async loadSecrets() {
    // In production, fetch from AWS Secrets Manager
    if (process.env.NODE_ENV === 'production') {
      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1',
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
      });

      try {
        const data = await client.getSecretValue({
          SecretId: process.env.SECRETS_ARN || 'prod/app-secrets'
        }).promise();

        this.secrets = JSON.parse(data.SecretString);
        this.lastFetch = Date.now();

        // Redact secrets from logs
        console.log('Secrets loaded successfully');
        return this.secrets;
      } catch (err) {
        console.error('Failed to load secrets from AWS:', err.message);
        throw new Error('Failed to load secrets');
      }
    } else {
      // Development/Test: load from environment
      this.secrets = {
        databaseUrl: process.env.DATABASE_URL,
        aws: {
          accessKeyId: process.env.AWS_ACCESS_KEY_ID,
          secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
        },
        apiKeys: {
          anthropic: process.env.ANTHROPIC_API_KEY,
          stripe: process.env.STRIPE_SECRET_KEY,
          logfire: process.env.LOGFIRE_TOKEN
        }
      };
      return this.secrets;
    }
  }

  getCachedSecrets() {
    if (!this.secrets || Date.now() - this.lastFetch > this.cacheExpiry) {
      throw new Error('Secrets need to be refreshed');
    }
    return this.secrets;
  }

  // Individual secret accessors with logging redaction
  getDatabaseUrl() {
    return this.secrets.databaseUrl;
  }

  getStripeKey() {
    return this.secrets.apiKeys?.stripe;
  }

  destroy() {
    // Clear secrets from memory
    this.secrets = {};
  }
}

module.exports = new SecretsManager();
```

