const crypto = require('crypto');

function validateSecret(key, value, pattern) {
  if (!value) {
    throw new Error(`Missing required secret: ${key}`);
  }

  // Check format
  if (pattern && !pattern.test(value)) {
    throw new Error(`Invalid format for secret: ${key}`);
  }

  // Check for default/example values
  const suspiciousPatterns = [
    /example\.com/i,
    /changeme/i,
    /your-.*-key/i,
    /test_value/i,
    /@todo/i
  ];

  for (const pattern of suspiciousPatterns) {
    if (pattern.test(value)) {
      console.warn(`⚠️  Potential placeholder detected: ${key}`);
    }
  }

  return true;
}

function validateAllSecrets(config) {
  const errors = [];

  try {
    validateSecret('DATABASE_URL', config.databaseUrl, /^postgres:\/\//);
  } catch (err) {
    errors.push(err.message);
  }

  try {
    validateSecret('AWS_ACCESS_KEY_ID', config.aws.accessKeyId, /^AKIA[A-Z0-9]{16}$/);
  } catch (err) {
    errors.push(err.message);
  }

  try {
    validateSecret('AWS_SECRET_ACCESS_KEY', config.aws.secretAccessKey, /^[A-Za-z0-9\/+=]{40}$/);
  } catch (err) {
    errors.push(err.message);
  }

  try {
    validateSecret('STRIPE_SECRET_KEY', config.apiKeys.stripe, /^sk_(live|test)_/);
  } catch (err) {
    errors.push(err.message);
  }

  if (errors.length > 0) {
    throw new Error(`Configuration errors:\n${errors.join('\n')}`);
  }

  console.log('✓ All secrets validated');
  return true;
}

module.exports = { validateSecret, validateAllSecrets };
