**Add to startup scripts or environment:**
```javascript
const fs = require('fs');
const path = require('path');

function secureEnvFiles() {
  const envDir = path.join(__dirname, '..');
  const envFiles = fs.readdirSync(envDir).filter(f => f.startsWith('.env'));

  for (const file of envFiles) {
    const filePath = path.join(envDir, file);
    // Set owner read/write only (0600)
    fs.chmodSync(filePath, 0o600);
    console.log(`Secured permissions for: ${file}`);
  }
}

// Call before loading config
if (process.env.NODE_ENV !== 'test') {
  secureEnvFiles();
}
